/* @lc app=leetcode id=2105 lang=kotlin */ class Solution { fun minimumRefill(plants: IntArray, capacityA: Int, capacityB: Int): Int = (plants.size / 2).let { mid -> (0 until mid).fold(Triple(0, capacityA, capacityB)) { (res, a, b), i -> Triple(res + (if (a < plants[i]) 1 else 0) + (if (b < plants[plants.size - 1 - i]) 1 else 0), if (a < plants[i]) capacityA - plants[i] else a - plants[i], if (b < plants[plants.size - 1 - i]) capacityB - plants[plants.size - 1 - i] else b - plants[plants.size - 1 - i]) }.let { (res, a, b) -> res + if (plants.size % 2 == 1 && maxOf(a, b) < plants[mid]) 1 else 0 } } }